ength":100},"name":{"type":"string","maxLength":20000},"amount":{"type":"string","maxLength":20000},"unit":{"type":"string","enum":["reps","seconds","minutes","meters","rounds","instructions"]},"sets":{"type":"integer","minimum":1,"maximum":100},"counting":{"type":"string","enum":["total","1=1","2=1","per side","cadence","time","distance","not applicable"]},"instructions":{"type":"string","maxLength":20000}},"required":["id","name","amount","unit","counting","instructions"],"additionalProperties":false},"maxItems":100}},"required":["id","title","instructions","minutes","exercises"],"additionalProperties":false},"minItems":1,"maxItems":50}},"required":["id","kind","title","blocks"],"additionalProperties":false},"minItems":1,"maxItems":3},"rawNotes":{"type":"string","maxLength":20000},"adaptationNotes":{"type":"string","maxLength":20000},"provenance":{"type":"object","properties":{"status":{"type":"string","enum":["illustrative","personal","imported-unreviewed","regional-reviewed"]},"label":{"type":"string","maxLength":20000},"sourceId":{"type":"string","maxLength":100},"q":{"type":"string","maxLength":160},"ao":{"type":"string","maxLength":160},"eventDate":{"type":"string","pattern":"^\\d{4}-\\d{2}-\\d{2}$"},"checkedAt":{"type":"string","format":"date-time"},"issues":{"type":"array","items":{"type":"string","maxLength":500},"maxItems":30},"durationBasis":{"type":"string","enum":["source","inferred","unknown"]},"generation":{"type":"object","properties":{"provider":{"type":"string","enum":["OpenRouter","Gemini"]},"model":{"type":"string","maxLength":200},"referenceSourceIds":{"type":"array","items":{"type":"string","maxLength":100},"maxItems":3}},"required":["provider","model","referenceSourceIds"],"additionalProperties":false},"url":{"type":"string","format":"uri","maxLength":2000}},"required":["status","label"],"additionalProperties":false},"schedule":{"type":"object","properties":{"startTime":{"type":"string","pattern":"^([01]\\d|2[0-3]):[0-5]\\d$"},"requiredFeatures":{"type":"array","items":{"type":"string","enum":["track","stairs","bleachers","parkingLot","shelter","hills","field","pullupBars","benches","walls","runningRoute"]},"maxItems":11,"default":[]},"siteSummary":{"type":"string","maxLength":1600}},"required":["startTime"],"additionalProperties":false},"updatedAt":{"type":"string","format":"date-time"}},"required":["schemaVersion","id","title","summary","kind","duration","equipment","running","format","sections","rawNotes","adaptationNotes","provenance","updatedAt"],"additionalProperties":false}},"$schema":"http://json-schema.org/draft-07/schema#"}$schema$::json,item) then return false; end if;
    select array_agg(value->>'kind') into kinds from jsonb_array_elements(item->'sections');
    if not ('thang'=any(kinds)) or cardinality(kinds)<>(select count(distinct k) from unnest(kinds) k) then return false; end if;
